#!/usr/bin/env node
/**
 * check-native-appid.mjs — Sync-guard for the premium native project appId.
 *
 * INCIDENT HISTORY (2026-06-11):
 *   A FREE_BUILD cap sync was accidentally run without an isolated temp dir,
 *   which left android/app/src/main/assets/capacitor.config.json and
 *   ios/App/App/capacitor.config.json tainted with appId 'com.werdumfight.free'.
 *   These files are gitignored (regenerated by `npx cap sync`) so the taint
 *   wasn't immediately visible. This guard catches the mistake LOUDLY.
 *
 * WHAT IT DOES:
 *   Reads both generated capacitor.config.json files from the committed native
 *   project trees (premium app, currently in App Store / Play Store review) and
 *   FAILS with exit code 1 if either contains an appId !== 'com.werdumfight.app'.
 *
 * RUN IT:
 *   node scripts/check-native-appid.mjs
 *   (or via npm script: npm run check:native)
 *
 * WHEN TO RUN:
 *   - After any `npx cap sync` targeting the premium project (android/ or ios/)
 *   - As part of pre-deploy checks for the premium build
 *   - After any build script that might inadvertently sync native projects
 *
 * HOW FREE-BUILD SYNC STAYS ISOLATED:
 *   The free-variant cap sync scripts (cap:free:sync:android / cap:free:sync:ios)
 *   use CAPACITOR_ANDROID_PATH / CAPACITOR_IOS_PATH pointed at mktemp dirs,
 *   so they NEVER touch android/ or ios/ in this repo. This guard is a second
 *   line of defence in case a developer runs a raw `npx cap sync` without the
 *   FREE_BUILD env guard.
 *
 * WOULD FAIL IF:
 *   Running `FREE_BUILD=1 npx cap sync` without CAPACITOR_ANDROID_PATH /
 *   CAPACITOR_IOS_PATH overrides would write 'com.werdumfight.free' into both
 *   native config files, and this script would exit 1 with a clear message.
 */

import { readFileSync, existsSync } from 'node:fs'
import { resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const ROOT = resolve(__dirname, '..')

const EXPECTED_APP_ID = 'com.werdumfight.app'

const NATIVE_CONFIGS = [
  {
    label: 'Android',
    path: resolve(ROOT, 'android', 'app', 'src', 'main', 'assets', 'capacitor.config.json'),
  },
  {
    label: 'iOS',
    path: resolve(ROOT, 'ios', 'App', 'App', 'capacitor.config.json'),
  },
]

let allOk = true

for (const { label, path } of NATIVE_CONFIGS) {
  if (!existsSync(path)) {
    console.warn(`[check:native] WARN  ${label}: config not found at ${path} — skipping`)
    continue
  }

  let parsed
  try {
    const raw = readFileSync(path, 'utf8')
    parsed = JSON.parse(raw)
  } catch (err) {
    console.error(`[check:native] ERROR ${label}: could not read/parse config — ${err.message}`)
    allOk = false
    continue
  }

  const actual = parsed?.appId ?? '(absent)'

  if (actual === EXPECTED_APP_ID) {
    console.log(`[check:native] OK    ${label}: appId = ${actual}`)
  } else {
    console.error(`
[check:native] FAIL  ${label}: appId MISMATCH!
  Expected : ${EXPECTED_APP_ID}
  Got      : ${actual}
  File     : ${path}

  *** PREMIUM NATIVE PROJECT IS TAINTED ***

  This means a FREE_BUILD cap sync ran against the premium native project
  instead of a throwaway temp directory. The files android/ and ios/ committed
  in this repo belong to the PREMIUM app (com.werdumfight.app) which is in
  App Store / Play Store review — DO NOT submit with this appId.

  To fix:
    1. Run: npx cap sync  (without FREE_BUILD=1 — restores premium appId)
    2. Re-run: node scripts/check-native-appid.mjs  (should pass now)

  To safely sync the FREE variant, always use the isolated scripts:
    npm run cap:free:sync:android
    npm run cap:free:sync:ios
  These point to a mktemp directory and NEVER touch android/ or ios/ here.
`)
    allOk = false
  }
}

if (!allOk) {
  process.exit(1)
}

console.log('[check:native] PASS  All native appIds confirmed as com.werdumfight.app')
